{
  "requirement_id": "REQ-004",
  "cases": [
    {
      "id": "TC-1",
      "title": "Create task successfully via form and verify instant display without page reload",
      "surface": "ui",
      "steps": [
        "Open /?user=alice&project=1",
        "Wait for body attribute data-ready to be true",
        "Type 'New UI Task' into element with testid 'new-title'",
        "Click element with testid 'create-btn'"
      ],
      "expected": "透過表單建立任務成功後，列表須立即顯示新任務，不需重新整理頁面。"
    },
    {
      "id": "TC-2",
      "title": "Task title containing HTML tags is displayed as plain literal text without element parsing",
      "surface": "ui",
      "steps": [
        "Open /?user=alice&project=1",
        "Wait for body attribute data-ready to be true",
        "Type '<b>Bold Title</b>' into element with testid 'new-title'",
        "Click element with testid 'create-btn'"
      ],
      "expected": "任務標題須以純文字顯示：標題若含 HTML 標記（例如 <b>x</b>），畫面上應顯示字面文字，不得被解析成元素。"
    },
    {
      "id": "TC-3",
      "title": "Display error message in the error area when an API error occurs",
      "surface": "ui",
      "steps": [
        "Open /?user=alice&project=99999",
        "Wait for body attribute data-ready to be true"
      ],
      "expected": "API 錯誤時於錯誤區顯示訊息。"
    }
  ]
}

